import React, { useState } from 'react';
import {
  Box,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Typography,
} from '@mui/material';
import ComplianceTrackShell from './ComplianceTrackShell';
import GpsGeotaggedCapture from './GpsGeotaggedCapture';
import {
  GEOTAGGED_EVIDENCE_GROUPS,
  GEOTAGGED_EVIDENCE_HREF,
} from '../../constants/complianceHub';
import {
  GEOTAGGED_EVIDENCE_WORKFLOWS,
  GeotaggedEvidenceWorkflow,
} from '../../constants/geotaggedEvidenceWorkflows';
import { useUrlSectionParam } from '../../hooks/useUrlSectionParam';

const GeotaggedEvidenceCapturePage: React.FC = () => {
  const [period] = useState('annual');
  const [section, setSection] = useUrlSectionParam('geotagged-capture', ['geotagged-capture']);
  const [workflow, setWorkflow] = useState<GeotaggedEvidenceWorkflow>('cbam_installation_boundary');

  return (
    <ComplianceTrackShell
      trackTitle="GPS geotagged evidence"
      trackDescription="Capture site photos with automatic GPS embedded in the image for CBAM, EUDR, ISO, PAT, and buyer compliance reporting."
      trackPath={GEOTAGGED_EVIDENCE_HREF}
      sectionGroups={GEOTAGGED_EVIDENCE_GROUPS}
      activeSection={section}
      onSectionChange={setSection}
      period={period}
      onPeriodChange={() => {}}
    >
      <Stack spacing={3}>
        <Typography variant="body1" color="text.secondary">
          Open this screen on-site at your factory, warehouse, or supplier plot. Location permission
          is required — coordinates feed into the system automatically with no manual entry.
        </Typography>

        <FormControl fullWidth sx={{ maxWidth: 420 }}>
          <InputLabel id="geotagged-workflow-label">Evidence purpose</InputLabel>
          <Select
            labelId="geotagged-workflow-label"
            label="Evidence purpose"
            value={workflow}
            onChange={(event) => setWorkflow(event.target.value as GeotaggedEvidenceWorkflow)}
          >
            {GEOTAGGED_EVIDENCE_WORKFLOWS.map((entry) => (
              <MenuItem key={entry.id} value={entry.id}>
                {entry.label}
              </MenuItem>
            ))}
          </Select>
        </FormControl>

        <Box>
          <GpsGeotaggedCapture workflow={workflow} period={period} />
        </Box>
      </Stack>
    </ComplianceTrackShell>
  );
};

export default GeotaggedEvidenceCapturePage;
